<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/accounting_ledger.php';
require_once __DIR__.'/includes/ui_shell.php';
staffRequireActivePosition('finance_manager');
header('Cache-Control: no-store, private');
function alH(mixed $value):string{return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function alMinor(string $value):int{if(!preg_match('/^-?\d{1,10}(?:[.,]\d{1,2})?$/D',$value))throw new AccountingLedgerException('Částku zadejte v Kč s nejvýše dvěma desetinnými místy.');$negative=str_starts_with($value,'-');$parts=explode('.',str_replace(',','.',ltrim($value,'-')));return ($negative?-1:1)*((int)$parts[0]*100+(int)str_pad($parts[1]??'',2,'0'));}
function alMoney(int $minor):string{return number_format($minor/100,2,',',' ').' Kč';}
function alCommon(string $action,?string $requestKey=null):void{?><input type="hidden" name="action" value="<?=alH($action)?>"><input type="hidden" name="csrf_token" value="<?=alH(csrf_token())?>"><input type="hidden" name="request_key" value="<?=alH($requestKey??bin2hex(random_bytes(16)))?>"><?php }
function alAudit(array $values=[]):void{?><label>Důvod<input class="form-control" name="reason" required minlength="10" maxlength="1000" value="<?=alH($values['reason']??'')?>"></label><label class="d-block my-2"><input type="checkbox" name="confirmed" value="1" required <?=($values['confirmed']??'')==='1'?'checked':''?>> Ověřil/a jsem podklady a potvrzuji zápis.</label><button class="btn btn-primary">Uložit s auditní stopou</button><?php }
function alAccountSelect(array $accounts,string $name='account_id'):void{?><select class="form-select" name="<?=alH($name)?>" required><option value="">Vyberte účet / pokladnu</option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>"><?=alH($a['name'].' ('.$a['code'].')')?></option><?php endforeach;?></select><?php }
function alEvidence():void{?><label>Skutečné datum<input class="form-control" type="date" name="effective_on" required max="<?=date('Y-m-d')?>"></label><label>Podklad / reference výpisu<input class="form-control" name="evidence" required maxlength="2000"></label><?php }
$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
    if(!csrf_verify((string)($_POST['csrf_token']??'')))throw new AccountingLedgerException('Formulář vypršel. Obnovte stránku.',403);
    $actor=(int)$_SESSION['trener_id'];$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirmed']??'')==='1';$action=(string)($_POST['action']??'');$accountId=(int)($_POST['account_id']??0);$date=(string)($_POST['effective_on']??'');$evidence=(string)($_POST['evidence']??'');$key=(string)($_POST['request_key']??'');
    if($action==='account')accountingLedgerCreateAccount($pdo,['code'=>(string)($_POST['code']??''),'name'=>(string)($_POST['name']??''),'kind'=>(string)($_POST['kind']??''),'currency'=>'CZK','opened_on'=>$date,'opening_minor'=>alMinor((string)($_POST['amount']??'')),'evidence'=>$evidence],$actor,$reason,$confirmed);
    elseif($action==='source')accountingLedgerReconcileSource($pdo,(string)($_POST['source_type']??''),(int)($_POST['source_id']??0),$accountId,$date,$evidence,$actor,$reason,$confirmed,empty($_POST['allocation_effective_on'])?null:(string)$_POST['allocation_effective_on'],empty($_POST['original_movement_id'])?null:(int)$_POST['original_movement_id']);
    elseif($action==='link')accountingLedgerLinkSource($pdo,(int)($_POST['movement_id']??0),(string)($_POST['source_type']??''),(int)($_POST['source_id']??0),$actor,$reason,$confirmed);
    elseif($action==='movement')accountingLedgerRecord($pdo,['account_id'=>$accountId,'kind'=>(string)($_POST['kind']??''),'amount_minor'=>alMinor((string)($_POST['amount']??'')),'currency'=>'CZK','effective_on'=>$date,'source_context'=>'manual-account-'.$accountId,'source_reference'=>(string)($_POST['reference']??''),'request_key'=>$key,'evidence'=>$evidence],$actor,$reason,$confirmed);
    elseif($action==='transfer')accountingLedgerTransfer($pdo,$accountId,(int)($_POST['target_account_id']??0),alMinor((string)($_POST['amount']??'')),alMinor((string)($_POST['fee']??'0')),$date,(string)($_POST['reference']??''),$evidence,$actor,$reason,$confirmed,empty($_POST['received_on'])?null:(string)$_POST['received_on']);
    elseif($action==='count')accountingLedgerReconcileAccount($pdo,$accountId,$date,alMinor((string)($_POST['amount']??'')),$evidence,($_POST['close']??'')==='1',$actor,$reason,$confirmed);
    elseif($action==='allocate')accountingLedgerAllocate($pdo,(int)($_POST['movement_id']??0),(string)($_POST['case_type']??''),(int)($_POST['case_id']??0),alMinor((string)($_POST['amount']??'')),$key,$actor,$reason,$confirmed,empty($_POST['reverses_id'])?null:(int)$_POST['reverses_id'],(string)($_POST['classification_code']??''),(string)($_POST['activity_code']??''),$date);
    elseif($action==='classify'){
        $splits=[];foreach(preg_split('/\R/u',(string)($_POST['splits']??'')) as $line){$parts=explode(';',trim($line));if(count($parts)!==2||!ctype_digit(trim($parts[0])))throw new AccountingLedgerException('Každý řádek členění má tvar ID pravidla;částka Kč.');$splits[]=['rule_id'=>(int)trim($parts[0]),'amount_minor'=>alMinor(trim($parts[1]))];}
        accountingLedgerClassify($pdo,(int)($_POST['movement_id']??0),$splits,$key,$actor,$reason,$confirmed);
    }else throw new AccountingLedgerException('Neznámá akce.');
    header('Location: accounting_ledger_admin.php?saved=1');exit;
}catch(Throwable $e){http_response_code($e instanceof AccountingLedgerException?($e->getCode()===403?403:422):500);$error=$e instanceof PDOException?'Zápis selhal bez částečného uložení.':$e->getMessage();}
$accounts=$pdo->query('SELECT * FROM accounting_accounts ORDER BY id')->fetchAll(PDO::FETCH_ASSOC);
$movements=$pdo->query('SELECT m.*,a.name AS account_name FROM accounting_movements m JOIN accounting_accounts a ON a.id=m.account_id ORDER BY m.id DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC);
$pending=accountingLedgerPendingSources($pdo,200);
$rules=accountingLedgerTable($pdo,'accounting_rules')?$pdo->query('SELECT * FROM accounting_rules ORDER BY id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC):[];
$allocationMovement=max(0,(int)($_GET['allocation_movement_id']??0));
$allocationSql='SELECT a.*,m.source_reference,ac.name AS account_name,
    COALESCE((SELECT SUM(r.amount_minor) FROM accounting_allocations r WHERE r.reverses_id=a.id),0) AS released_minor
    FROM accounting_allocations a JOIN accounting_movements m ON m.id=a.movement_id
    JOIN accounting_accounts ac ON ac.id=m.account_id';
$allocationQuery=$pdo->prepare($allocationSql.($allocationMovement>0?' WHERE a.movement_id=?':'').' ORDER BY a.id DESC LIMIT 200');
$allocationQuery->execute($allocationMovement>0?[$allocationMovement]:[]);
$allocations=$allocationQuery->fetchAll(PDO::FETCH_ASSOC);
$allocationCaseLabels=['shop_order'=>'Objednávka','member_charge'=>'Členský předpis','shop_return'=>'Doplatek výměny'];
$releaseAllocation=null;$releaseWarning='';
if((int)($_GET['release_allocation_id']??0)>0){
    $releaseQuery=$pdo->prepare($allocationSql.' WHERE a.id=?');$releaseQuery->execute([(int)$_GET['release_allocation_id']]);$candidate=$releaseQuery->fetch(PDO::FETCH_ASSOC);
    if($candidate&&(int)$candidate['amount_minor']>0&&(int)$candidate['amount_minor']+(int)$candidate['released_minor']>0&&isset($allocationCaseLabels[$candidate['case_type']]))$releaseAllocation=$candidate;
    else $releaseWarning='Vybraný příděl není dostupný pro uvolnění v tomto formuláři. Ověřte jeho stav v přehledu.';
}
$allocationInput=$releaseAllocation?[
    'movement_id'=>$releaseAllocation['movement_id'],'case_type'=>$releaseAllocation['case_type'],'case_id'=>$releaseAllocation['case_id'],
    'amount'=>number_format(-((int)$releaseAllocation['amount_minor']+(int)$releaseAllocation['released_minor'])/100,2,'.',''),
    'reverses_id'=>$releaseAllocation['id'],'classification_code'=>$releaseAllocation['classification_code'],'activity_code'=>$releaseAllocation['activity_code'],
]:[];
$allocationRetry=$_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='allocate';
if($allocationRetry){
    // A failed partial release must never become the full suggested release on retry.
    foreach(['movement_id','case_type','case_id','amount','reverses_id','classification_code','activity_code','effective_on','request_key','reason','confirmed'] as $field)$allocationInput[$field]=(string)($_POST[$field]??'');
}
?><!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Peněžní pohyby a pokladny</title><?php appUiAssets();?></head><body><?php include __DIR__.'/hlavicka.php';?><main class="container py-4"><h1>Peněžní pohyby a pokladny</h1>
<p>Jeden skutečný příjem, samostatné rozdělení na závazky a samostatné účetní členění. Potvrzení objednávky ani přidělení rodinné platby nevytváří další peníze. Neznámé historické účty a data doplňte podle podkladů.</p>
<?php if($error):?><div class="alert alert-danger"><?=alH($error)?></div><?php elseif(isset($_GET['saved'])):?><div class="alert alert-success">Zápis byl uložen.</div><?php endif;?>
<h2>Účty a pokladny</h2><table class="table"><thead><tr><th>Účet</th><th>Počáteční stav</th><th>Zůstatek k dnešku</th></tr></thead><tbody><?php foreach($accounts as $account):$b=accountingLedgerBalance($pdo,(int)$account['id'],date('Y-m-d'));?><tr><td>#<?=(int)$account['id']?> <?=alH($account['name'])?></td><td><?=alH($account['opened_on'].' · '.alMoney((int)$account['opening_minor']))?></td><td><?=alH(alMoney($b['closing_minor']))?></td></tr><?php endforeach;?></tbody></table>
<details class="mb-3"><summary>Založit účet nebo pokladnu s doloženým počátečním stavem</summary><form method="post" class="border p-3"><?php alCommon('account');?><label>Kód<input name="code" required maxlength="60" class="form-control"></label><label>Název<input name="name" required maxlength="160" class="form-control"></label><label>Druh<select name="kind" class="form-select"><option value="cash">Pokladna</option><option value="bank">Banka</option><option value="provider">Platební brána / zúčtovací účet</option></select></label><label>Počáteční stav Kč<input name="amount" required class="form-control"></label><?php alEvidence();alAudit();?></form></details>
<details class="mb-3"><summary>Inventura hotovosti / odsouhlasení výpisu</summary><form method="post" class="border p-3"><?php alCommon('count');alAccountSelect($accounts);alEvidence();?><label>Skutečně zjištěný zůstatek Kč<input name="amount" required class="form-control"></label><label class="d-block"><input name="close" value="1" type="checkbox"> Uzavřít účet do tohoto dne (další zpětné pohyby budou zablokované).</label><?php alAudit();?></form></details>
<h2>Podklady čekající na účetní zařazení</h2><p>Zobrazeno nejvýše 200 zdrojů. Původní stav platby se zde nemění. Skutečné datum je povinné i u historicky potvrzené platby.</p>
<?php foreach($pending as $source):?><details class="mb-2"><summary><?=alH($source['source_type'].' #'.$source['source_id'].' · '.alMoney($source['amount_minor']).' · '.($source['effective_on']??'datum neověřeno'))?></summary><?php if(isset($source['error'])):?><p class="text-danger"><?=alH($source['error'])?></p><?php else:?><form method="post" class="border p-3"><?php alCommon('source');?><input type="hidden" name="source_type" value="<?=alH($source['source_type'])?>"><input type="hidden" name="source_id" value="<?=(int)$source['source_id']?>"><?php alAccountSelect($accounts);?><label>Skutečné datum<input type="date" name="effective_on" value="<?=alH($source['effective_on']??'')?>" required class="form-control"></label><label>Podklad<input name="evidence" required class="form-control"></label><label>Doložené datum původního rozdělení, pokud u zdroje chybí<input type="date" name="allocation_effective_on" class="form-control"></label><label>Původní příjem vratky – ID pohybu (u rodinného rozdělení)<input type="number" min="1" name="original_movement_id" class="form-control"></label><?php alAudit();?></form><form method="post" class="border p-3 mt-1"><?php alCommon('link');?><input type="hidden" name="source_type" value="<?=alH($source['source_type'])?>"><input type="hidden" name="source_id" value="<?=(int)$source['source_id']?>"><label>Nebo propojit s již zapsaným převodem – ID pohybu<input type="number" min="1" name="movement_id" required class="form-control"></label><?php alAudit();?></form><?php endif;?></details><?php endforeach;?>
<details class="my-3"><summary>Ostatní doložený příjem nebo výdaj mimo existující zdroje</summary><form method="post" class="border p-3"><p>Platby objednávek a importované výpisy přiřaďte výše. Vratku zadejte přes rozhodnutí o vratce. Částka výdaje/poplatku je záporná.</p><?php alCommon('movement');alAccountSelect($accounts);?><select name="kind" class="form-select"><option value="income">Ostatní příjem</option><option value="expense">Ostatní výdaj</option><option value="fee">Poplatek</option></select><label>Částka Kč<input name="amount" required class="form-control"></label><label>Jedinečná reference pohybu<input name="reference" required maxlength="160" class="form-control"></label><?php alEvidence();alAudit();?></form></details>
<details class="my-3"><summary>Převod mezi vlastními účty / vypořádání brány</summary><form method="post" class="border p-3"><p>Převáděná částka je čisté připsání na cílový účet. Poplatek se samostatně odečte ze zdrojového účtu. Následně propojte bankovní výpis s existující stranou převodu.</p><?php alCommon('transfer');?><label>Z účtu<?php alAccountSelect($accounts);?></label><label>Na účet<?php alAccountSelect($accounts,'target_account_id');?></label><label>Převáděná částka Kč<input name="amount" required class="form-control"></label><label>Poplatek Kč (odečtený v den odeslání)<input name="fee" value="0" required class="form-control"></label><label>Datum skutečného připsání na cílový účet<input name="received_on" type="date" required class="form-control"></label><label>Jedinečná reference převodu<input name="reference" required maxlength="80" class="form-control"></label><?php alEvidence();alAudit();?></form></details>
<h2>Peněžní kniha</h2><p>Nejnovějších 200 pohybů. Částky jsou samostatné proti rozdělení pohledávek, dokladům a skladovým vratkám.</p><div class="table-responsive"><table class="table"><thead><tr><th>ID / účet</th><th>Skutečné datum</th><th>Datum zápisu</th><th>Druh / částka</th><th>Podklad</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td>#<?=(int)$m['id']?> <?=alH($m['account_name'])?></td><td><?=alH($m['effective_on'])?></td><td><?=alH($m['recorded_at'])?></td><td><?=alH($m['kind'].' · '.alMoney((int)$m['amount_minor']))?></td><td><?=alH($m['source_context'].':'.$m['source_reference'].' · '.$m['evidence'])?></td></tr><?php endforeach;?></tbody></table></div>
<section id="allocations" class="my-4"><h2>Příděly na pohledávky a jejich uvolnění</h2>
<p>Nejnovějších 200 přídělů podle filtru. ID přídělu je samostatné od ID peněžního pohybu a případu. Uvolnění přídělu samo nevrací peníze.</p>
<form method="get" class="d-flex align-items-end gap-2 mb-3"><label>ID peněžního pohybu<input class="form-control" name="allocation_movement_id" type="number" min="1" value="<?=$allocationMovement?:''?>"></label><button class="btn btn-outline-primary">Vyhledat příděly</button><a href="accounting_ledger_admin.php#allocations">Zrušit filtr</a></form>
<div class="table-responsive"><table class="table"><thead><tr><th>ID přídělu / datum</th><th>Peněžní pohyb / účet</th><th>Cílový případ</th><th>Částka</th><th>Stav uvolnění</th><th>Další krok</th></tr></thead><tbody>
<?php foreach($allocations as $allocation):$remaining=(int)$allocation['amount_minor']+(int)$allocation['released_minor']; ?>
<tr id="allocation-<?=(int)$allocation['id']?>"><td>#<?=(int)$allocation['id']?><br><?=alH($allocation['effective_on'])?></td>
<td><a href="?allocation_movement_id=<?=(int)$allocation['movement_id']?>#allocations">Pohyb #<?=(int)$allocation['movement_id']?></a><br><?=alH($allocation['account_name'].' · '.$allocation['source_reference'])?></td>
<td><?=alH(($allocationCaseLabels[$allocation['case_type']]??$allocation['case_type']).' #'.$allocation['case_id'])?></td><td><?=alH(alMoney((int)$allocation['amount_minor']))?></td>
<td><?php if((int)$allocation['amount_minor']<0):?>Uvolnění přídělu #<?=(int)$allocation['reverses_id']?><?php else:?>Uvolněno <?=alH(alMoney(-(int)$allocation['released_minor']))?><br><?=$remaining>0?'Zbývá '.alH(alMoney($remaining)):'Plně uvolněno'?><?php endif;?></td>
<td><?php if((int)$allocation['amount_minor']>0&&$remaining>0&&isset($allocationCaseLabels[$allocation['case_type']])):?><a href="?<?=alH(http_build_query(['allocation_movement_id'=>$allocation['movement_id'],'release_allocation_id'=>$allocation['id']]))?>#allocation-form">Připravit uvolnění</a><?php endif;?></td></tr>
<?php endforeach;?><?php if($allocations===[]):?><tr><td colspan="6">Pro tento filtr nebyl nalezen žádný příděl.</td></tr><?php endif;?></tbody></table></div></section>
<?php if($releaseWarning!==''):?><p class="alert alert-warning"><?=alH($releaseWarning)?></p><?php endif;?>
<details class="my-3" id="allocation-form" <?=$releaseAllocation||$allocationRetry?'open':''?>><summary>Rozdělit pohyb na pohledávku / uvolnit původní rozdělení</summary><form method="post" class="border p-3"><p>Jde o účetní vazbu, která sama nepotvrzuje úhradu v obchodní agendě. Přesun proveďte uvolněním a novým přidělením.</p>
<?php if($releaseAllocation&&!$allocationRetry):?><p>Vybrán příděl #<?=(int)$releaseAllocation['id']?>. Ověřte zápornou částku, skutečné datum a podklad. Uvolnění proběhne až po potvrzení formuláře; dostupný zůstatek se při uložení znovu ověří.</p><?php endif;alCommon('allocate',$allocationInput['request_key']??null);?>
<label>ID pohybu<input type="number" min="1" name="movement_id" required class="form-control" value="<?=alH($allocationInput['movement_id']??'')?>"></label>
<label>Druh případu<select name="case_type" class="form-select"><?php if($allocationRetry&&!isset($allocationCaseLabels[$allocationInput['case_type']])):?><option value="<?=alH($allocationInput['case_type'])?>" selected>Neplatný výběr – zvolte druh případu</option><?php endif;?><?php foreach($allocationCaseLabels as $type=>$label):?><option value="<?=alH($type)?>" <?=($allocationInput['case_type']??'')===$type?'selected':''?>><?=alH($label)?></option><?php endforeach;?></select></label>
<label>ID případu<input type="number" min="1" name="case_id" required class="form-control" value="<?=alH($allocationInput['case_id']??'')?>"></label>
<label>Částka Kč (uvolnění záporně)<input name="amount" required class="form-control" value="<?=alH($allocationInput['amount']??'')?>"></label>
<label>Původní ID rozdělení při uvolnění<input type="number" min="1" name="reverses_id" class="form-control" value="<?=alH($allocationInput['reverses_id']??'')?>"></label>
<input type="hidden" name="classification_code" value="<?=alH($allocationInput['classification_code']??'')?>"><input type="hidden" name="activity_code" value="<?=alH($allocationInput['activity_code']??'')?>">
<label>Datum přidělení / uvolnění<input name="effective_on" type="date" required class="form-control" value="<?=alH($allocationInput['effective_on']??'')?>"></label><?php alAudit($allocationRetry?$allocationInput:[]);?></form></details>
<details class="my-3"><summary>Účetní členění pohybu</summary><p>Nezávislé na úhradě pohledávek. Úplný součet musí odpovídat absolutní částce pohybu. Nová verze zachová předchozí členění.</p><ul><?php foreach($rules as $r):?><li>#<?=(int)$r['id']?> <?=alH($r['category_code'].' · '.$r['activity'].' · '.$r['title'].' od '.$r['valid_from'])?></li><?php endforeach;?></ul><form method="post" class="border p-3"><?php alCommon('classify');?><label>ID pohybu<input name="movement_id" type="number" min="1" required class="form-control"></label><label>Řádky: ID pravidla;částka Kč<textarea name="splits" required class="form-control" rows="4"></textarea></label><?php alAudit();?></form></details>
